ACTION_LETTERS = %w[N E S W].freeze

class World
  attr_reader :rows, :cols, :kinds, :wind, :terminal_rewards, :states, :terminals,
              :state_index, :terminal_index, :start, :start_state

  def self.read(path)
    lines = File.readlines(path, chomp: true)
    rows = lines[0].split[1].to_i
    cols = lines[1].split[1].to_i
    kinds = lines[2, rows].join
    wind = lines[rows + 2].split[1].chars.map(&:to_i)
    rewards = lines[rows + 3].split.drop(1).map(&:to_i)
    new(rows, cols, kinds, wind, rewards)
  end

  def initialize(rows, cols, kinds, wind, rewards)
    @rows, @cols, @kinds, @wind, @terminal_rewards = rows, cols, kinds, wind, rewards
    @states, @terminals = [], []
    @state_index = Array.new(kinds.length)
    @terminal_index = Array.new(kinds.length)
    kinds.each_char.with_index do |kind, cell|
      if kind == "G" || kind == "P"
        @terminal_index[cell] = @terminals.length
        @terminals << cell
      elsif kind != "#"
        @state_index[cell] = @states.length
        @states << cell
      end
    end
    @start = kinds.index("S")
    @start_state = @state_index[@start]
  end

  def terminal?(cell)
    !@terminal_index[cell].nil?
  end

  def terminal_name(cell)
    @kinds[cell] == "G" ? "goal" : "pit"
  end

  def move(cell, direction)
    target = cell + [-@cols, 1, @cols, -1][direction]
    target = cell if @kinds[target] == "#"
    return target if terminal?(target)

    @wind[cell % @cols].times do
      above = target - @cols
      break if @kinds[above] == "#"

      target = above
      break if terminal?(target)
    end
    target
  end
end

class RandomGenerator
  def initialize(seed)
    @value = seed
  end

  def draw
    @value = (48_271 * @value) % 2_147_483_647
  end
end

class Environment
  attr_reader :world, :slip_total, :moves, :transitions

  def initialize(world, step_reward, slip_total, floor_slip, ice_slip)
    @world, @step_reward, @slip_total = world, step_reward, slip_total
    @floor_slip, @ice_slip = floor_slip, ice_slip
    @moves = world.states.map { |cell| Array.new(4) { |direction| world.move(cell, direction) } }
    @transitions = world.states.each_index.map do |state|
      Array.new(4) do |action|
        slip_outcomes(state, action).filter_map do |direction, numerator|
          [@moves[state][direction], numerator] if numerator.positive?
        end
      end
    end
  end

  def slip(state)
    @world.kinds[@world.states[state]] == "~" ? @ice_slip : @floor_slip
  end

  def slip_outcomes(state, action)
    p = slip(state)
    [[action, @slip_total - 2 * p], [(action + 1) % 4, p], [(action + 3) % 4, p]]
  end

  def reward(cell)
    terminal = @world.terminal_index[cell]
    terminal.nil? ? @step_reward : @world.terminal_rewards[terminal]
  end

  def step(generator, state, action)
    draw = generator.draw % @slip_total
    p = slip(state)
    direction = if draw < @slip_total - 2 * p
                  action
                elsif draw < @slip_total - p
                  (action + 1) % 4
                else
                  (action + 3) % 4
                end
    cell = @moves[state][direction]
    [cell, reward(cell)]
  end
end

module MonteCarlo
  module_function

  def discounted_return(rewards, gamma)
    rewards.reverse_each.reduce(0) { |value, reward| 10_000 * reward + (gamma * value).div(100) }
  end
end

class ReturnAverages
  def initialize(state_count)
    @sums = Array.new(state_count) { Array.new(4, 0) }
    @counts = Array.new(state_count) { Array.new(4, 0) }
  end

  def update(q_values, history, gamma)
    first = {}
    history.each_with_index { |(state, action, _), index| first[[state, action]] ||= index }
    value = 0
    (history.length - 1).downto(0) do |index|
      state, action, reward = history[index]
      value = 10_000 * reward + (gamma * value).div(100)
      next unless first[[state, action]] == index

      @sums[state][action] += value
      @counts[state][action] += 1
      q_values[state][action] = @sums[state][action].div(@counts[state][action])
    end
  end
end

require_relative "dynamic_programming"

module TDLearning
  module_function

  def choose(generator, q_row, epsilon)
    return generator.draw % 4 if generator.draw % 1000 < epsilon

    DynamicProgramming.first_max(q_row)
  end

  def td_target(reward, terminal, next_value, gamma)
    10_000 * reward + (terminal ? 0 : (gamma * next_value).div(100))
  end

  def next_value(q_row, epsilon = nil)
    return q_row.max if epsilon.nil?

    (epsilon * q_row.sum + 4 * (1000 - epsilon) * q_row.max).div(4000)
  end

  def td_update(q_row, action, target, alpha)
    q_row[action] += (alpha * (target - q_row[action])).div(100)
  end
end

class DynaModel
  include TDLearning

  def initialize(state_count)
    @outcomes = Array.new(state_count) { Array.new(4) }
    @pairs = []
  end

  def record(state, action, reward, next_state)
    @pairs << [state, action] if @outcomes[state][action].nil?
    @outcomes[state][action] = [reward, next_state]
  end

  def plan(generator, q_values, gamma, alpha, count)
    count.times do
      state, action = @pairs[generator.draw % @pairs.length]
      reward, next_state = @outcomes[state][action]
      terminal = next_state.nil?
      future = terminal ? 0 : next_value(q_values[next_state])
      td_update(q_values[state], action, td_target(reward, terminal, future, gamma), alpha)
    end
  end
end
